<script setup lang="ts">
import type {ApiClient,InsuranceQuote} from '@kuaixie/sdk';
import {useInsuranceSelection} from './useInsurance';
const props=defineProps<{client:ApiClient;subjectType:'trip'|'pk_quote'|'order';subjectId:string;itemName:string;declaredValue:string}>();const emit=defineEmits<{selected:[quote:InsuranceQuote|null]}>();
const p=useInsuranceSelection(props.client,()=>({subjectType:props.subjectType,subjectId:props.subjectId,itemName:props.itemName,declaredValue:props.declaredValue}),value=>emit('selected',value));
</script>
<template><section class="business-card"><h3>{{$t('insurance.choose')}}</h3><p>{{$t('insurance.boundary')}}</p><details><summary>{{$t('insurance.directory')}}</summary><p v-for="company in p.companies.value" :key="company.code">{{company.name}} · {{$t('insurance.referenceOnly')}}</p></details><p v-if="!p.products.value.length">{{$t('insurance.noProducts')}}</p><select v-model="p.product.value" :disabled="p.busy.value"><option value="">{{$t('insurance.choose')}}</option><option v-for="item in p.products.value" :key="item.id" :value="item.id">{{item.insurerName}} · {{item.kind}} · {{item.name}}</option></select><button type="button" :disabled="p.busy.value||!p.product.value||!declaredValue||!itemName.trim()" @click="p.preview">{{$t('insurance.quote')}}</button><p v-if="p.error.value" role="alert">{{p.error.value}}</p><template v-if="p.quote.value"><strong>{{p.quote.value.insurerName}} · {{p.quote.value.productName}}</strong><p>{{$t('insurance.directPremium')}} {{p.quote.value.premium+' '+p.quote.value.currency}}</p><p>{{$t('insurance.notIssued')}} · {{p.quote.value.expiresAt}}</p><nav class="business-tabs"><a :href="p.quote.value.termsUrl" target="_blank" rel="noopener noreferrer">{{$t('insurance.terms')}}</a><a :href="p.quote.value.exclusionsUrl" target="_blank" rel="noopener noreferrer">{{$t('insurance.exclusions')}}</a><a :href="p.quote.value.claimsUrl" target="_blank" rel="noopener noreferrer">{{$t('insurance.claims')}}</a></nav></template></section></template>
